INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','movement-prepositions','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"movement-prepositions","title":"Prepositions of movement and direction","level":"A2","order":19,"summary":"Follow a route through space and distinguish a position from a change of position.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["A destination or entry","Leaving and crossing","Following or approaching","Read the whole route"],"rules":[{"title":"A destination or entry","explanation":"To points to a destination; into emphasises movement from outside to inside. In usually describes an inside position. Onto highlights movement to a surface, while on commonly describes contact or position on that surface.","pattern":"We went **to** the station and **into** the building.","commonMistakes":["Go home normally has no to because home functions adverbially in this construction."],"examples":["Choose the route preposition: “We walked **into** the studio.” The route is from outside to inside the studio.","Choose the route preposition: “We walked **into** the cottage.” The route is from outside to inside the cottage."],"skill":"form"},{"title":"Leaving and crossing","explanation":"Out of indicates movement from inside to outside. Across usually describes travel from one side of a space or surface to another. Through describes travel within an opening, passage or surrounding area. The physical route makes the difference.","pattern":"Walk **across** the road, then **through** the gate.","commonMistakes":["Across a tunnel suggests crossing its width or going over its location; through a tunnel follows its interior route."],"examples":["What route does “walk into the studio” describe in this exercise? → **from outside to inside the studio**","What route does “walk into the cottage” describe in this exercise? → **from outside to inside the cottage**"],"skill":"meaning"},{"title":"Following or approaching","explanation":"Along follows the length of something such as a path or river. Towards indicates direction but does not necessarily imply arrival. Past means movement beyond a point; around can describe a route surrounding or avoiding something.","pattern":"Walk **along** the path **towards** the bridge.","commonMistakes":["Towards does not by itself say that the destination was reached."],"examples":["After walking into the studio, we went **—** home. Choose the usual adverbial home construction.","After walking into the cottage, we went **—** home. Choose the usual adverbial home construction."],"skill":"contrast"},{"title":"Read the whole route","explanation":"A route can combine several prepositions because each describes a different relation. Identify starting point, boundary, path and destination. Some movements allow several descriptions, so these questions specify the intended route rather than treating all alternatives as wrong in every context.","pattern":"Go **out of** the house, **across** the square and **into** the café.","commonMistakes":["In and into can overlap with some verbs. The questions explicitly test the entry/exit distinction."],"examples":["After walking into the studio, we walked towards the station. What does “towards” establish? → **The direction, without necessarily establishing arrival.**","After walking into the cottage, we walked towards the station. What does “towards” establish? → **The direction, without necessarily establishing arrival.**"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-prepositions-reference"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"dc662ef6-509e-5004-af5d-ce89f4ecde44","topicSlug":"movement-prepositions","level":"A2","prompt":"Choose the route preposition: “We walked ____ the studio.” The route is from outside to inside the studio.","choices":[{"id":"A","text":"beside"},{"id":"B","text":"into"},{"id":"C","text":"above"},{"id":"D","text":"beneath"}],"answerId":"B","hint":"Trace the **route described in words** before choosing the preposition.","explanation":"**into the studio** expresses the specified route: from outside to inside the studio.","keywords":["movement-route"],"skill":"movement-route","contextKey":"movement-prepositions-1","fingerprint":"e07a7bc033e40c0fd4792c1c20edc9e3873b5b21e6792abc82d4217e6eeb556b","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-prepositions-reference"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Trace the **route described in words** before choosing the preposition.","**into the studio** expresses the specified route: from outside to inside the studio.","Choose **into**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Beside expresses being next to it, not the described passage or crossing.","B":"**into the studio** expresses the specified route: from outside to inside the studio.","C":"Above expresses a higher position, not this specified route.","D":"Beneath expresses a lower position, not this specified route."}}},{"id":"b8f6c5f5-046a-5384-a4c1-f7865c2ac249","topicSlug":"movement-prepositions","level":"A2","prompt":"What route does “walk into the studio” describe in this exercise?","choices":[{"id":"A","text":"stay above it without moving"},{"id":"B","text":"stay underneath it without moving"},{"id":"C","text":"from outside to inside the studio"},{"id":"D","text":"remain motionless next to it"}],"answerId":"C","hint":"Distinguish **movement along a route** from a static position.","explanation":"The intended meaning of **into** here is **from outside to inside the studio**.","keywords":["movement-meaning"],"skill":"movement-meaning","contextKey":"movement-prepositions-1","fingerprint":"33fb1c5ad5e4413f09366985e42da62e9be3b35b913e5bb70df1f920a035df67","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-prepositions-reference"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Distinguish **movement along a route** from a static position.","The intended meaning of **into** here is **from outside to inside the studio**.","Choose **from outside to inside the studio**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The phrase describes a route, not a stationary higher position.","B":"The phrase describes movement, not a stationary lower position.","C":"The intended meaning of **into** here is **from outside to inside the studio**.","D":"Walk describes movement, and beside would indicate the neighbouring position."}}},{"id":"a3825f64-f81e-5c59-acff-6cd3b5af14f6","topicSlug":"movement-prepositions","level":"A2","prompt":"After walking into the studio, we went ____ home. Choose the usual adverbial home construction.","choices":[{"id":"A","text":"at"},{"id":"B","text":"in"},{"id":"C","text":"—"},{"id":"D","text":"to"}],"answerId":"C","hint":"Home behaves differently from a noun destination such as **the house**.","explanation":"In **went home**, home functions adverbially and takes no to.","keywords":["destination-home"],"skill":"destination-home","contextKey":"movement-prepositions-1","fingerprint":"ef921c6a6f4d2140c285325d569a261dd7f668e2206c2bbd75d8841729ca6fb8","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-prepositions-reference"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Home behaves differently from a noun destination such as **the house**.","In **went home**, home functions adverbially and takes no to.","Choose **—**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"At home describes a position, not the ordinary go home destination construction.","B":"In home is not the ordinary destination phrase.","C":"In **went home**, home functions adverbially and takes no to.","D":"The usual construction is go home, without to."}}},{"id":"30f25bac-8880-58e2-ac64-da5d3003ab78","topicSlug":"movement-prepositions","level":"A2","prompt":"After walking into the studio, we walked towards the station. What does “towards” establish?","choices":[{"id":"A","text":"That we certainly arrived at the station."},{"id":"B","text":"That we remained inside the station."},{"id":"C","text":"That we walked away from the station."},{"id":"D","text":"The direction, without necessarily establishing arrival."}],"answerId":"D","hint":"Separate **direction** from **successful arrival**.","explanation":"**Towards** points in the station’s direction but does not guarantee that we reached it.","keywords":["direction-no-arrival"],"skill":"direction-no-arrival","contextKey":"movement-prepositions-1","fingerprint":"82e08b8c1eae99f54df5332c95c455256d4d7d0e44dc54d752ce9656bd8546c4","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-prepositions-reference"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Separate **direction** from **successful arrival**.","**Towards** points in the station’s direction but does not guarantee that we reached it.","Choose **The direction, without necessarily establishing arrival.**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Towards alone does not assert arrival.","B":"That would describe a static inside position, not direction.","C":"Away from gives the opposite direction.","D":"**Towards** points in the station’s direction but does not guarantee that we reached it."}}},{"id":"04c320ab-f4a5-5e45-aead-d4f9fa1e2d91","topicSlug":"movement-prepositions","level":"A2","prompt":"Choose the route preposition: “We walked ____ the cottage.” The route is from outside to inside the cottage.","choices":[{"id":"A","text":"above"},{"id":"B","text":"beneath"},{"id":"C","text":"beside"},{"id":"D","text":"into"}],"answerId":"D","hint":"Trace the **route described in words** before choosing the preposition.","explanation":"**into the cottage** expresses the specified route: from outside to inside the cottage.","keywords":["movement-route"],"skill":"movement-route","contextKey":"movement-prepositions-2","fingerprint":"1ba167168cc65d30c7e3f2b6af65dbdedebb04d34b95151ff9259ab0d5e6d9e7","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-prepositions-reference"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Trace the **route described in words** before choosing the preposition.","**into the cottage** expresses the specified route: from outside to inside the cottage.","Choose **into**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Above expresses a higher position, not this specified route.","B":"Beneath expresses a lower position, not this specified route.","C":"Beside expresses being next to it, not the described passage or crossing.","D":"**into the cottage** expresses the specified route: from outside to inside the cottage."}}},{"id":"045da9b1-8b5e-542d-ad90-07aafa0b24c1","topicSlug":"movement-prepositions","level":"A2","prompt":"What route does “walk into the cottage” describe in this exercise?","choices":[{"id":"A","text":"stay above it without moving"},{"id":"B","text":"stay underneath it without moving"},{"id":"C","text":"from outside to inside the cottage"},{"id":"D","text":"remain motionless next to it"}],"answerId":"C","hint":"Distinguish **movement along a route** from a static position.","explanation":"The intended meaning of **into** here is **from outside to inside the cottage**.","keywords":["movement-meaning"],"skill":"movement-meaning","contextKey":"movement-prepositions-2","fingerprint":"6571f2bf91e8c47425596849a46a58988bb9f3f4d14ec62cdfb7fb72e8b521d0","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-prepositions-reference"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Distinguish **movement along a route** from a static position.","The intended meaning of **into** here is **from outside to inside the cottage**.","Choose **from outside to inside the cottage**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The phrase describes a route, not a stationary higher position.","B":"The phrase describes movement, not a stationary lower position.","C":"The intended meaning of **into** here is **from outside to inside the cottage**.","D":"Walk describes movement, and beside would indicate the neighbouring position."}}},{"id":"430dba2c-02b2-590b-a645-844544af9067","topicSlug":"movement-prepositions","level":"A2","prompt":"After walking into the cottage, we went ____ home. Choose the usual adverbial home construction.","choices":[{"id":"A","text":"in"},{"id":"B","text":"—"},{"id":"C","text":"to"},{"id":"D","text":"at"}],"answerId":"B","hint":"Home behaves differently from a noun destination such as **the house**.","explanation":"In **went home**, home functions adverbially and takes no to.","keywords":["destination-home"],"skill":"destination-home","contextKey":"movement-prepositions-2","fingerprint":"42e5ed46ad6ee852ac3676aa3a99c56352e478510d79c86867f6cff71382b97d","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-prepositions-reference"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Home behaves differently from a noun destination such as **the house**.","In **went home**, home functions adverbially and takes no to.","Choose **—**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"In home is not the ordinary destination phrase.","B":"In **went home**, home functions adverbially and takes no to.","C":"The usual construction is go home, without to.","D":"At home describes a position, not the ordinary go home destination construction."}}},{"id":"ce1075d4-5f96-50d9-ad97-25ce0054df22","topicSlug":"movement-prepositions","level":"A2","prompt":"After walking into the cottage, we walked towards the station. What does “towards” establish?","choices":[{"id":"A","text":"That we certainly arrived at the station."},{"id":"B","text":"That we remained inside the station."},{"id":"C","text":"That we walked away from the station."},{"id":"D","text":"The direction, without necessarily establishing arrival."}],"answerId":"D","hint":"Separate **direction** from **successful arrival**.","explanation":"**Towards** points in the station’s direction but does not guarantee that we reached it.","keywords":["direction-no-arrival"],"skill":"direction-no-arrival","contextKey":"movement-prepositions-2","fingerprint":"e95401a8e1978e2c2b548565340020f0c3004c6c41526b00440f3dca2f0ac69b","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-prepositions-reference"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Separate **direction** from **successful arrival**.","**Towards** points in the station’s direction but does not guarantee that we reached it.","Choose **The direction, without necessarily establishing arrival.**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Towards alone does not assert arrival.","B":"That would describe a static inside position, not direction.","C":"Away from gives the opposite direction.","D":"**Towards** points in the station’s direction but does not guarantee that we reached it."}}},{"id":"ea85edbf-ec6f-5f53-ae16-c675e65064b7","topicSlug":"movement-prepositions","level":"A2","prompt":"Choose the route preposition: “We walked ____ the garage.” The route is from outside to inside the garage.","choices":[{"id":"A","text":"above"},{"id":"B","text":"beneath"},{"id":"C","text":"beside"},{"id":"D","text":"into"}],"answerId":"D","hint":"Trace the **route described in words** before choosing the preposition.","explanation":"**into the garage** expresses the specified route: from outside to inside the garage.","keywords":["movement-route"],"skill":"movement-route","contextKey":"movement-prepositions-3","fingerprint":"026acaa4691c95568875f56d593ab8a0aa348546c3e0ea2e261fe40aef7c6406","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-prepositions-reference"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Trace the **route described in words** before choosing the preposition.","**into the garage** expresses the specified route: from outside to inside the garage.","Choose **into**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Above expresses a higher position, not this specified route.","B":"Beneath expresses a lower position, not this specified route.","C":"Beside expresses being next to it, not the described passage or crossing.","D":"**into the garage** expresses the specified route: from outside to inside the garage."}}},{"id":"6ffa5a63-0cfe-59e8-a4b7-0816145f0f9e","topicSlug":"movement-prepositions","level":"A2","prompt":"What route does “walk into the garage” describe in this exercise?","choices":[{"id":"A","text":"stay underneath it without moving"},{"id":"B","text":"from outside to inside the garage"},{"id":"C","text":"remain motionless next to it"},{"id":"D","text":"stay above it without moving"}],"answerId":"B","hint":"Distinguish **movement along a route** from a static position.","explanation":"The intended meaning of **into** here is **from outside to inside the garage**.","keywords":["movement-meaning"],"skill":"movement-meaning","contextKey":"movement-prepositions-3","fingerprint":"a5fc4d505eab1b91f2901f8ed637acbb5d116f383e149f5e0c0de49ef09daa56","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-prepositions-reference"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Distinguish **movement along a route** from a static position.","The intended meaning of **into** here is **from outside to inside the garage**.","Choose **from outside to inside the garage**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The phrase describes movement, not a stationary lower position.","B":"The intended meaning of **into** here is **from outside to inside the garage**.","C":"Walk describes movement, and beside would indicate the neighbouring position.","D":"The phrase describes a route, not a stationary higher position."}}},{"id":"f8825eb6-b406-58cb-a9ca-51884c684a8c","topicSlug":"movement-prepositions","level":"A2","prompt":"After walking into the garage, we went ____ home. Choose the usual adverbial home construction.","choices":[{"id":"A","text":"in"},{"id":"B","text":"—"},{"id":"C","text":"to"},{"id":"D","text":"at"}],"answerId":"B","hint":"Home behaves differently from a noun destination such as **the house**.","explanation":"In **went home**, home functions adverbially and takes no to.","keywords":["destination-home"],"skill":"destination-home","contextKey":"movement-prepositions-3","fingerprint":"43ee84b8aa668fee1629abfb9e661892d20d06a90a713d32af002816d4d2ad62","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-prepo